"""Origins source snapshot imported from anabaptistorigins.org, 2026-10-08."""
import json,re
from pathlib import Path
from html import escape as e
from bs4 import BeautifulSoup
ROOT=Path(__file__).parent
DATA=ROOT/'content/origins'
def build_origins(write):
 eps=json.loads((DATA/'episodes.json').read_text()); photos=json.loads((DATA/'gallery.json').read_text()); places=json.loads((DATA/'locations-enriched.json').read_text())
 (ROOT/'dist/assets/origins/locations.json').write_text(json.dumps(places,ensure_ascii=False))
 def shell(body,active='Overview'):
  tabs=[('Overview',''),('Episodes','episodes/'),('The map','locations/'),('Gallery','gallery/'),('Resources','resources/'),('About the series','about/')]
  return '<link rel="stylesheet" href="/assets/origins/origins.css?v=resources-episodes-1"><div class="origins"><div class="wrap origins-nav"><a class="origins-wordmark" href="/origins/">origins<span>An Anabaptist Perspectives series</span></a><nav aria-label="Origins">'+''.join(f'<a {"aria-current=page" if active==n else ""} href="/origins/{p}">{n}</a>' for n,p in tabs)+'</nav></div>'+body+'</div>'
 def cards(items):
  return '<div class="origins-episodes">'+''.join(f'<article class="origin-episode"><a href="/origins/episodes/{x["slug"]}/"><div class="episode-image"><img src="{e(x["image"])}" alt="{e(x["title"])}" loading="lazy"><span class="episode-number">{x["number"]}</span></div><div class="episode-copy"><p class="meta">{x["duration"]} <span>·</span> {x["years"]}</p><h3>{e(x["title"])}</h3><p>{e(x["description"])}</p><span class="origin-link">Watch episode ↗</span></div></a></article>' for x in items)+'</div>'
 def heading(k,t,d):return f'<div class="origins-heading"><p class="eyebrow">{k}</p><h1>{t}</h1><p>{d}</p></div>'
 scenic=photos[7]['image'];hero=f'''<section class="wrap"><div class="origins-hero" style="--scene:url('{scenic}')"><div class="origins-hero-copy"><p class="eyebrow">A ten-part documentary series</p><h1>A different path.<br>A lasting faith.</h1><p>Travel back 500 years to the people and places that shaped the Anabaptist movement.</p><div class="origin-actions"><a class="btn" href="/origins/episodes/{eps[0]['slug']}/">Start watching <span aria-hidden="true">↗</span></a><a class="origin-ghost" href="https://youtu.be/EWVXsq-gUQ4">Watch the trailer</a></div></div><div class="hero-caption">Zürich, Switzerland <span>Where the story begins · 1525</span></div></div><div class="origins-facts"><span><strong>10</strong> episodes in the series</span><span><strong>6</strong> countries visited</span><span><strong>500</strong> years of perspective</span></div></section>'''
 mapcta=f'''<section class="wrap section"><div class="origin-map-teaser"><div><p class="eyebrow">History has a place.</p><h2>Follow the story.<br>Find yourself there.</h2><p>From the streets of Zürich to the moat at Asperen, explore the places behind the convictions.</p><a class="btn" href="/origins/locations/">Explore the interactive map ↗</a><p class="small">{len(places)} mapped locations across six countries</p></div><a href="/origins/locations/" class="map-teaser-art" aria-label="Explore locations"><img src="{e(photos[3]['image'])}" alt="Aerial view of the moat at Asperen" loading="lazy"><span><i aria-hidden="true">●</i> Asperen, Netherlands<br><small>Dirk Willems turned back here.</small></span></a></div></section>'''
 write('/origins/','Anabaptist Origins — Documentary & Interactive Map','Watch Anabaptist Origins and explore the historic locations, photographs and resources behind this documentary series.',shell(hero+f'<section class="wrap section"><div class="origin-section-head"><div><p class="eyebrow">Watch the series</p><h2>Convictions that changed lives.</h2></div><a class="origin-link" href="/origins/episodes/">All episodes ↗</a></div>{cards(eps[:3])}</section>'+mapcta+f'<section class="wrap section origin-photo-callout"><img src="{e(photos[15]["image"])}" alt="Schleitheim Confession" loading="lazy"><div><p class="eyebrow">Look closer</p><h2>The history beyond the screen.</h2><p>Explore manuscripts, places, and objects filmed for the series, and keep studying with the reading list and historical timeline.</p><div class="origin-actions"><a class="btn" href="/origins/gallery/">Open the gallery</a><a class="origin-link" href="/origins/resources/">Study resources ↗</a></div></div></section>'))
 write('/origins/episodes/','Origins Episodes','Watch the published episodes of Anabaptist Origins.',shell('<section class="wrap section">'+heading('The documentary','A story worth returning to.','Six episodes now available from the ten-part Origins series. Begin with Dirk Willems, then follow the movement across Europe.')+cards(eps)+'</section>','Episodes'))
 for x in eps:
  s=BeautifulSoup((DATA/(x['slug']+'.html')).read_text(),'html.parser').select_one('main'); vid=s.select_one('[data-iframe-src]');match=re.search(r'/embed/([\w-]+)',vid.get('data-iframe-src','')) if vid else None
  content=[];started=False
  for tag in s.select('h2,h3,p'):
   text=tag.get_text(' ',strip=True)
   if text=='About This Episode':started=True
   if started and text:
    if text in ['Related Episodes','More Episodes','Explore More']:break
    if tag.name in ['h2','h3']:content.append(f'<h2>{e(text)}</h2>')
    else:content.append('<p>'+e(text)+'</p>')
  player=f'<iframe src="https://www.youtube-nocookie.com/embed/{match[1]}" title="{e(x["title"])}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen loading="lazy"></iframe>' if match else f'<a href="{e(x["source"])}">Watch on the original Origins website</a>'
  body=f'<section class="wrap section">{heading(x["number"]+" · "+x["duration"],e(x["title"]),e(x["description"]))}<div class="origin-player">{player}</div><div class="origin-reading">'+''.join(content)+f'<p><a href="{e(x["source"])}">Original episode & credits ↗</a></p></div></section>'
  write('/origins/episodes/'+x['slug']+'/',x['title']+' — Origins',x['description'],shell(body,'Episodes'))
 gallery='<section class="wrap section">'+heading('The visual archive','Closer to the story.','The manuscripts, places, objects, and faces behind Origins.')+'<div class="origins-gallery">'+''.join(f'<figure><a href="{e(p["full"])}" target="_blank" rel="noopener"><img src="{e(p["image"])}" alt="{e(p["caption"])}" loading="lazy"></a><figcaption>{e(p["caption"])}</figcaption></figure>' for p in photos)+'</div></section>'
 write('/origins/gallery/','Origins Photo Gallery','Explore photographs of the historic places and manuscripts behind Anabaptist Origins.',shell(gallery,'Gallery'))
 for name,title,intro in [('about','The people behind the journey.','A documentary series from Anabaptist Perspectives.')]:
  s=BeautifulSoup((DATA/(name+'.html')).read_text(),'html.parser');parts=[]
  for tag in s.select('h2,h3,h4,p'):
   text=tag.get_text(' ',strip=True)
   if not text or text=='Read More':continue
   parts.append(f'<{tag.name}>{e(text)}</{tag.name}>')
  if name=='resources':parts.insert(0,'<div class="origin-actions"><a class="btn" href="https://anabaptistorigins.org/wp-content/uploads/2026/07/Further_Reading_and_Resources.pdf">Reading list ↗</a><a class="btn outline" href="https://anabaptistorigins.org/wp-content/uploads/2026/07/Master_Timeline.pdf">Full timeline ↗</a></div>')
  else:
   imgs=s.select('img');parts.insert(0,'<div class="origin-team-images">'+''.join(f'<img src="{e(im["src"])}" alt="{e(im.get("alt","Origins presenter"))}" loading="lazy">' for im in imgs[:3])+'</div>')
  write('/origins/'+name+'/',('About Origins' if name=='about' else 'Origins Study Resources'),intro,shell('<section class="wrap section">'+heading('Anabaptist Origins',title,intro)+'<div class="origin-reading">'+''.join(parts)+'</div></section>','About the series' if name=='about' else 'Resources'))

 timeline=[
 ('1415','Hus is executed','The Czech reformer is burned for challenging church authority.'),
 ('c. 1450','The printing revolution','Gutenberg’s press helps Reformation ideas travel.'),
 ('1517','Luther’s protest','The Protestant Reformation begins.'),
 ('1519','Reform comes to Zürich','Zwingli’s New Testament preaching draws students to the Grossmünster.'),
 ('1525','Baptism by conviction','The Zürich circle practices adult baptism, beginning the Anabaptist movement.'),
 ('1527','A shared confession','Schleitheim’s seven articles articulate the communities’ beliefs.'),
 ('1534–1535','The catastrophe at Münster','An armed faction’s rule ends violently, damaging the wider movement.'),
 ('1536','Menno Simons joins the movement','The former priest becomes a guiding leader.'),
 ('1569','Dirk Willems rescues his pursuer','His act of mercy leads to recapture and execution.'),
 ('1632','The Dordrecht Confession','Eighteen articles shape Mennonite and Amish belief.'),
 ('1660','Remembering the martyrs','Van Braght compiles accounts of persecution in Martyrs Mirror.')]
 pdfroot='https://anabaptistorigins.org/wp-content/uploads/2026/07/'
 download_icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3v12m-5-5 5 5 5-5M4 16v3a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-3"/></svg>'
 resources=f'''<section class="wrap origin-resources"><div class="resource-intro"><div><p class="eyebrow">The Origins study companion</p><h1>Keep exploring.</h1><p>The screen is only the beginning. Follow the history, discover the sources, and make room for a deeper understanding.</p><div class="origin-actions"><a class="btn" href="#study-downloads">Explore the resources ↓</a><a class="origin-link" href="#origins-timeline">Follow the timeline</a></div></div><figure><img src="{e(photos[15]['image'])}" alt="The Schleitheim Confession, photographed for Origins"><figcaption>Words that shaped a movement · The Schleitheim Confession</figcaption></figure></div><div class="resource-downloads" id="study-downloads"><a class="resource-download" href="{pdfroot}Further_Reading_and_Resources.pdf" target="_blank" rel="noopener"><span class="resource-file-icon">{download_icon}</span><div><span class="resource-file-meta">Reading companion · 4-page PDF</span><h2>Further reading & resources</h2><p>Books, primary sources, and free online references, arranged around the series.</p><span class="origin-link">Open the reading list ↗</span></div></a><a class="resource-download" href="{pdfroot}Master_Timeline.pdf" target="_blank" rel="noopener"><span class="resource-file-icon">{download_icon}</span><div><span class="resource-file-meta">Historical reference · 5-page PDF</span><h2>The complete timeline</h2><p>A companion chronology of the people and events covered in Origins.</p><span class="origin-link">Open the full timeline ↗</span></div></a></div><section class="resource-timeline" id="origins-timeline"><div class="timeline-intro"><p class="eyebrow">1415—1660</p><h2>See the story<br>take shape.</h2><p>Eleven turning points from the original Origins timeline.</p><a class="origin-link" href="{pdfroot}Master_Timeline.pdf" target="_blank" rel="noopener">Read the complete chronology ↗</a><nav class="timeline-jumps" aria-label="Timeline eras"><a href="#timeline-1415">Before the movement <span>1415–1519</span></a><a href="#timeline-1525">Conviction takes root <span>1525–1536</span></a><a href="#timeline-1569">An enduring witness <span>1569–1660</span></a></nav></div><ol class="timeline-events">'''+''.join(f'<li id="timeline-{year.split("–")[0].replace("c. ","")}"><span class="timeline-year">{year}</span><div><h3>{title}</h3><p>{desc}</p></div></li>' for year,title,desc in timeline)+f'''</ol></section><section class="resource-reading"><div><p class="eyebrow">Where to begin</p><h2>A few books to start with.</h2><p>Selected from the series’ companion reading list.</p></div><div class="resource-books"><article><span>01 / An overview</span><h3>The Anabaptist Story</h3><p>William Estep</p></article><article><span>02 / The wider story</span><h3>An Introduction to Mennonite History</h3><p>Cornelius Dyck</p></article><article><span>03 / A defining essay</span><h3>The Anabaptist Vision</h3><p>Harold S. Bender</p></article></div><a class="origin-link" href="{pdfroot}Further_Reading_and_Resources.pdf" target="_blank" rel="noopener">Browse all recommended reading ↗</a></section><div class="resource-continue"><div><p class="eyebrow">Put a place to the story</p><h2>History is closer than you think.</h2><p>Visit the filming locations and open the stories behind them.</p></div><a class="btn" href="/origins/locations/">Explore the map ↗</a></div><p class="resource-credit">Adapted from the <a href="https://anabaptistorigins.org/resources/">original Origins resources</a>. Companion PDFs are provided by Anabaptist Origins.</p></section>'''
 write('/origins/resources/','Origins Study Resources — Reading & Historical Timeline','Explore the Origins historical timeline, companion reading list, and study resources.',shell(resources,'Resources'))
 mapbody='''<section class="wrap origin-atlas"><div class="origin-atlas-heading"><div><p class="eyebrow">The Origins field guide</p><h1>Walk into the story.</h1></div><p>Explore the places where conviction became history.<br>Choose a place to step inside its story.</p></div><div class="atlas-toolbar"><label><span>Find a location</span><input id="place-search" type="search" placeholder="Try Zürich, Dirk Willems, a church…"></label><label><span>Explore by country</span><select id="place-country"><option value="">All six countries</option><option>Austria</option><option>Czechia</option><option>France</option><option>Germany</option><option>Netherlands</option><option>Switzerland</option></select></label><label><span>Explore by episode</span><select id="place-episode" aria-describedby="episode-filter-help"><option value="">All episodes</option><option value="1">Episode 1</option><option value="2">Episode 2</option><option value="3">Episode 3</option><option value="4">Episode 4</option><option value="5">Episode 5</option><option value="6">Episode 6</option></select></label><button id="map-reset" class="origin-ghost" type="button">Reset map ↺</button></div><p id="episode-filter-help" class="atlas-filter-help">Filter locations featured in Episodes 1–6. All episodes includes locations from the wider series.</p><div class="atlas-layout"><aside class="atlas-sidebar" aria-label="Historic locations"><div class="atlas-count" id="place-count" aria-live="polite">46 locations to explore</div><div id="place-list" class="place-list"></div></aside><div class="atlas-map-wrap"><div id="origins-map" aria-label="Map of Anabaptist Origins filming locations"></div><div class="atlas-map-label"><span class="atlas-dot"></span> THE ORIGINS ATLAS <small>Europe · Six countries · One story</small></div></div></div><dialog id="location-story" class="location-story" aria-labelledby="story-title"><button class="story-close" type="button" aria-label="Close location story">✕</button><div id="story-content"></div></dialog><p class="atlas-source">Locations and historical notes from the <a href="https://anabaptistorigins.org/locations/">Origins filming map</a>. The public map currently includes 46 locations from the series’ 65 filming locations.</p><noscript><p>Enable JavaScript to explore the map, or <a href="https://anabaptistorigins.org/locations/">open the original filming map</a>.</p></noscript></section><link rel="stylesheet" href="/assets/origins/leaflet.css"><script defer src="/assets/origins/leaflet.js"></script><script defer src="/assets/origins/map.js?v=episode-filter-1"></script>'''
 write('/origins/locations/','Origins Interactive Map — Historic Anabaptist Locations','Explore 46 historic Anabaptist locations across six European countries, with photographs and notes from the Origins filming team.',shell(mapbody,'The map'))
